func substituteParams(command string, params map[string]string) string {
	result := command
	for k, v := range params {
		result = strings.ReplaceAll(result, "${"+k+"}", v)
	}
	return result
}

func evaluateCondition(cond string, params map[string]string) (bool, error) {
	cond = strings.TrimSpace(cond)
	if cond == "" {
		return true, nil
	}
	if strings.Contains(cond, "==") {
		parts := strings.SplitN(cond, "==", 2)
		left := resolveParam(strings.TrimSpace(parts[0]), params)
		right := resolveParam(strings.TrimSpace(parts[1]), params)
		return left == right, nil
	}
	if strings.Contains(cond, "!=") {
		parts := strings.SplitN(cond, "!=", 2)
		left := resolveParam(strings.TrimSpace(parts[0]), params)
		right := resolveParam(strings.TrimSpace(parts[1]), params)
		return left != right, nil
	}
	return false, fmt.Errorf("invalid condition: %s", cond)
}

func resolveParam(token string, params map[string]string) string {
	re := regexp.MustCompile(`^\$\{(.+)\}$`)
	m := re.FindStringSubmatch(token)
	if m != nil {
		return params[m[1]]
	}
	return token
}
