var variableTokenRe = regexp.MustCompile(`\$\{([^}]*)\}`)

func substituteVariables(command string, vars map[string]string) (string, error) {
	var firstErr error
	result := variableTokenRe.ReplaceAllStringFunc(command, func(token string) string {
		content := token[2 : len(token)-1]
		name, defaultVal, hasDefault := splitVariableDefault(content)
		if val, ok := vars[name]; ok {
			return val
		}
		if hasDefault {
			return defaultVal
		}
		if firstErr == nil {
			firstErr = fmt.Errorf("unresolved variable: %s", token)
		}
		return token
	})
	if firstErr != nil {
		return result, firstErr
	}
	return result, nil
}

func substituteStaticForDryRun(command string, params map[string]string, captureNames map[string]bool) (string, error) {
	var firstErr error
	result := variableTokenRe.ReplaceAllStringFunc(command, func(token string) string {
		content := token[2 : len(token)-1]
		name, defaultVal, hasDefault := splitVariableDefault(content)
		if captureNames[name] {
			return token
		}
		if val, ok := params[name]; ok {
			return val
		}
		if hasDefault {
			return defaultVal
		}
		if firstErr == nil {
			firstErr = fmt.Errorf("unresolved variable: %s", token)
		}
		return token
	})
	if firstErr != nil {
		return result, firstErr
	}
	return result, nil
}

func splitVariableDefault(content string) (string, string, bool) {
	if idx := strings.Index(content, ":-"); idx >= 0 {
		return content[:idx], content[idx+2:], true
	}
	return content, "", false
}

func evaluateCondition(cond string, vars map[string]string) (bool, error) {
	cond = strings.TrimSpace(cond)
	if cond == "" {
		return true, nil
	}
	if strings.Contains(cond, "==") {
		parts := strings.SplitN(cond, "==", 2)
		left, err := substituteVariables(strings.TrimSpace(parts[0]), vars)
		if err != nil {
			return false, err
		}
		right, err := substituteVariables(strings.TrimSpace(parts[1]), vars)
		if err != nil {
			return false, err
		}
		return left == right, nil
	}
	if strings.Contains(cond, "!=") {
		parts := strings.SplitN(cond, "!=", 2)
		left, err := substituteVariables(strings.TrimSpace(parts[0]), vars)
		if err != nil {
			return false, err
		}
		right, err := substituteVariables(strings.TrimSpace(parts[1]), vars)
		if err != nil {
			return false, err
		}
		return left != right, nil
	}
	return false, fmt.Errorf("invalid condition: %s", cond)
}
