func dryRunPipeline(cfg *PipelineConfig, params map[string]string) (map[string]interface{}, error) {
	if err := validatePipelineConfig(cfg); err != nil { return nil, err }
	merged := mergeParams(cfg.Parameters, params)
	captureNames := make(map[string]bool)
	for _, step := range cfg.Steps {
		if step.CaptureOutput != nil && step.CaptureOutput.Name != "" {
			captureNames[step.CaptureOutput.Name] = true
		}
	}
	status := make(map[string]string)
	assigned := make(map[string]bool)
	for len(assigned) < len(cfg.Steps) {
		progress := false
		for _, step := range cfg.Steps {
			if assigned[step.Name] { continue }
			depsKnown := true
			for _, dep := range step.DependsOn { if !assigned[dep] { depsKnown=false; break } }
			if !depsKnown { continue }
			depsOk := true
			for _, dep := range step.DependsOn {
				if status[dep] != "ready" && status[dep] != "skipped" { depsOk=false; break }
			}
			if !depsOk {
				status[step.Name] = "blocked"
			} else {
				cond, err := evaluateCondition(step.Condition, merged)
				if err != nil { return nil, fmt.Errorf("step %s condition: %w", step.Name, err) }
