func buildPipelineGraph(cfg *PipelineConfig) map[string]interface{} {
	nodes := make([]map[string]string, 0, len(cfg.Steps))
	for _, s := range cfg.Steps { nodes=append(nodes, map[string]string{"name":s.Name,"type":s.Type}) }
	edges := make([]map[string]string, 0)
	for _, s := range cfg.Steps { for _, dep := range s.DependsOn { edges=append(edges, map[string]string{"from":dep,"to":s.Name}) } }
	levels := computeLevels(cfg.Steps)
