}
func computeLevels(steps []*PipelineStep) [][]string {
	assigned := make(map[string]bool)
	var levels [][]string
	for len(assigned) < len(steps) {
		var level []string
		for _, s := range steps {
			if assigned[s.Name] { continue }
			ok := true
			for _, dep := range s.DependsOn { if !assigned[dep] { ok=false; break } }
			if ok { level = append(level, s.Name) }
		}
		if len(level)==0 { break }
		sort.Strings(level)
		for _, n := range level { assigned[n]=true }
		levels=append(levels, level)
	}
	return levels
}
