func parsePipelineParams(args []string) map[string]string {
	params := make(map[string]string)
	for i := 0; i < len(args); i++ {
		a := args[i]
		if a == "--param" {
			if i+1 < len(args) {
				rest := args[i+1]
				parts := strings.SplitN(rest, "=", 2)
				if len(parts) == 2 {
					params[parts[0]] = parts[1]
				}
				i++
			}
			continue
		}
		if strings.HasPrefix(a, "--param") && len(a) > len("--param") {
			rest := a[len("--param"):]
			if strings.HasPrefix(rest, "=") {
				rest = rest[1:]
			}
			if rest == "" {
				continue
			}
			parts := strings.SplitN(rest, "=", 2)
			if len(parts) == 2 {
				params[parts[0]] = parts[1]
			}
		}
	}
	return params
}
```
